+	text := fmt.Sprintf("entry %q has mode %s: %v", e.Name, e.Mode, cause)
+	kept := causesBesidesEOF(cause)
+	if kept == nil {
+		return errors.New(text)
+	}
+
+	return &subtreeEOFError{text: text, cause: kept}
