+// or nil when it joins none. An error that wraps io.EOF along a single chain
+// cannot be separated from it, so it is left out.
+func causesBesidesEOF(err error) error {
+	joined, ok := err.(interface{ Unwrap() []error })
+	if !ok {
+		return nil
+	}
