+	var kept []error
+	for _, c := range joined.Unwrap() {
+		if !errors.Is(c, io.EOF) {
+			kept = append(kept, c)
+			continue
+		}
+		if inner := causesBesidesEOF(c); inner != nil {
+			kept = append(kept, inner)
+		}
+	}
+
+	return errors.Join(kept...)
+}
